<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Edit Analisis</title><style>body{font-family:Arial;margin:30px;background:#f5f7fb;color:#172033}.card{background:#fff;padding:20px;border-radius:12px;max-width:900px;margin:auto}input,textarea,button{width:100%;box-sizing:border-box;padding:10px;margin:7px 0;border:1px solid #ccd3df;border-radius:7px}button{background:#173f7a;color:#fff}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}small{color:#667085}</style></head><body><div class="card"><h1>Edit {{$analysis->parameter}}</h1><small>Status setelah perubahan akan kembali ke DRAFT.</small><form method="post" action="{{route('analysis.update',$analysis)}}">@csrf @method('PUT')<label>Sample Code<input name="sample_code" value="{{old('sample_code',$analysis->sample_code)}}" required></label>@php($i=$analysis->inputs??[])<div class="grid">@if($analysis->parameter==='DO')@foreach([['thiosulfate_ml','Na2S2O3 Duplo A'],['thiosulfate_duplo_ml','Na2S2O3 Duplo B'],['normality','Normalitas'],['winkler_volume_ml','Volume Winkler'],['reagent_mnso4_ml','MnSO4'],['reagent_alkali_ml','Alkali Iodida Azida'],['aliquot_ml','Aliquot']] as $f)<label>{{$f[1]}}<input name="{{$f[0]}}" type="number" step="any" value="{{old($f[0],$i[$f[0]]??'')}}" @if($f[0]!=='thiosulfate_duplo_ml') required @endif></label>@endforeach @else @foreach([['a1','A1 DO hari 0'],['a2','A2 DO hari 5'],['b1','B1 blanko hari 0'],['b2','B2 blanko hari 5'],['vb','VB volume bibit blanko'],['vc','Vc volume bibit contoh'],['p','P faktor pengenceran']] as $f)<label>{{$f[1]}}<input name="{{$f[0]}}" type="number" step="any" value="{{old($f[0],$i[$f[0]]??'')}}" required></label>@endforeach @endif</div><label>Catatan<textarea name="notes">{{old('notes',$analysis->notes)}}</textarea></label><button>Simpan Perubahan & Hitung Ulang</button></form></div></body></html>